// The vendored family hotkey scheme (@chatgoose/hotkeys, generated by the hub's
// scripts/vendor-hotkeys.mjs — never hand-edited). The manifest pins every
// shipped file; the Fansly extension must carry the SAME sha256 (both clients
// run one scheme), which is checked at release time by comparing manifests.

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { HOTKEYS, HOTKEY_SCHEME_VERSION, createHotkeyEngine } from '@chatgoose/hotkeys';

const vendorRoot = resolve(import.meta.dirname, '../../../packages/chatgoose-hotkeys');
const manifest = JSON.parse(readFileSync(resolve(vendorRoot, 'chatgoose-hotkeys.vendor.json'), 'utf8')) as {
  schemeVersion: number;
  sha256: string;
  sourceCommit: string;
  files: Record<string, string>;
};

describe('vendored @chatgoose/hotkeys', () => {
  it('every shipped file matches its manifest hash, and the aggregate sha256 matches the file list', () => {
    expect(Object.keys(manifest.files).length).toBeGreaterThan(0);
    for (const [file, hash] of Object.entries(manifest.files)) {
      expect(createHash('sha256').update(readFileSync(resolve(vendorRoot, file))).digest('hex'), file).toBe(hash);
    }
    expect(manifest.sha256).toBe(createHash('sha256').update(JSON.stringify(manifest.files)).digest('hex'));
  });

  it('was vendored from a clean hub commit', () => {
    expect(manifest.sourceCommit).toMatch(/^[0-9a-f]{40}$/);
  });

  it('loads at runtime with the manifest scheme version', () => {
    expect(HOTKEY_SCHEME_VERSION).toBe(manifest.schemeVersion);
    expect(HOTKEYS.length).toBeGreaterThan(0);
    const engine = createHotkeyEngine({ platform: 'mac', client: 'desktop' });
    engine.keydown({ code: 'MetaLeft', key: 'Meta', metaKey: true, ctrlKey: false, altKey: false, shiftKey: false });
    expect(engine.keydown({ code: 'KeyE', key: 'e', metaKey: true, ctrlKey: false, altKey: false, shiftKey: false }))
      .toEqual({ kind: 'action', action: 'reply', repeat: false });
  });
});
